# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KIYI TİPLERİ VE OLUŞUM SÜREÇLERİ (COĞ.10.3.3)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">DAĞ UZANIŞI VE VADİ BOĞULMASINA GÖRE</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Boyuna Kıyı: Dağlar kıyıya paralel; girinti-çıkıntı az,</text>\n  <text x="45" y="104" font-size="11.2" fill="#1e3a8a">kıta sahanlığı dar, falez yaygın (Karadeniz, Akdeniz).</text>\n  <text x="35" y="128" font-size="11.2" fill="#1e3a8a">• Enine Kıyı: Dağlar kıyıya dik; koy/körfez/ada çok,</text>\n  <text x="45" y="144" font-size="11.2" fill="#1e3a8a">kıta sahanlığı geniş, iç kesime ulaşım kolay (Ege).</text>\n  <text x="35" y="168" font-size="11.2" fill="#1e3a8a">• Ria Kıyılar: Eski akarsu vadilerinin deniz altında</text>\n  <text x="45" y="184" font-size="11.2" fill="#1e3a8a">kalması (İstanbul-Çanakkale Boğazları, Haliç, Menteşe).</text>\n  <text x="35" y="206" font-size="11.2" fill="#1e3a8a">• Dalmaçya Kıyı: Kıyıya paralel adalar dizisi (Kaş-Finike).</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">BUZUL, GELGİT VE BİRİKİM ETKİSİNE GÖRE</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Limanlı Kıyı: Geniş vadilerin kıyı oklarıyla önünün</text>\n  <text x="380" y="104" font-size="11.2" fill="#14532d">kapanması (Büyükçekmece, Küçükçekmece, Sinop).</text>\n  <text x="370" y="128" font-size="11.2" fill="#14532d">• Fiyort ve Skyer Kıyılar: Buzul vadileri ve hörgüçkaya-</text>\n  <text x="380" y="144" font-size="11.2" fill="#14532d">ların sular altında kalması (Norveç; Türkiye\'de YOK).</text>\n  <text x="370" y="168" font-size="11.2" fill="#14532d">• Haliç (Estuar) ve Watt Kıyılar: Okyanus kıyılarında</text>\n  <text x="380" y="184" font-size="11.2" fill="#14532d">güçlü gelgit aşınımıyla oluşur (Kuzeybatı Avrupa).</text>\n  <text x="370" y="206" font-size="11.2" fill="#14532d">• Mercanlı (Resif) Kıyılar: Tropikal sıcak denizlerde.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Türkiye orta kuşakta yer aldığı için kıyılarında buzul (fiyort, skyer) ve tropikal mercan kıyıları görülmez.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TÜRKİYE KIYILARINDA GÖRÜLEN BAŞLICA KIYI TİPLERİ HARİTASI</text>\n  <rect x="22" y="42" width="210" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="127" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">KARADENİZ VE MARMARA</text>\n  <text x="32" y="88" font-size="10.8" fill="#78350f">• Karadeniz Kıyıları:</text>\n  <text x="40" y="105" font-size="10.5" fill="#78350f">Boyuna kıyı tipi (falezli, dar şelf)</text>\n  <text x="32" y="128" font-size="10.8" fill="#78350f">• İstanbul ve Çanakkale Boğazları:</text>\n  <text x="40" y="145" font-size="10.5" fill="#78350f">Ria kıyı tipi (eski akarsu vadisi)</text>\n  <text x="32" y="168" font-size="10.8" fill="#78350f">• Büyük ve Küçükçekmece, Sinop:</text>\n  <text x="40" y="185" font-size="10.5" fill="#78350f">Limanlı kıyı tipi (lagünlü/koylu)</text>\n  <text x="32" y="205" font-size="10.5" fill="#78350f">• Kapıdağ Yarımadası: Tombolo</text>\n  <rect x="245" y="42" width="210" height="175" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#075985">EGE DENİZİ KIYILARI</text>\n  <text x="255" y="88" font-size="10.8" fill="#0c4a6e">• Edremit - Kuşadası Arası:</text>\n  <text x="263" y="105" font-size="10.5" fill="#0c4a6e">Enine kıyı tipi (horst-grabenler</text>\n  <text x="263" y="120" font-size="10.5" fill="#0c4a6e">kıyıya dik uzanır)</text>\n  <text x="255" y="144" font-size="10.8" fill="#0c4a6e">• Güneybatı Anadolu (Menteşe):</text>\n  <text x="263" y="161" font-size="10.5" fill="#0c4a6e">Bodrum - Marmaris - Datça -</text>\n  <text x="263" y="176" font-size="10.5" fill="#0c4a6e">Fethiye çevresi Ria kıyı tipidir.</text>\n  <text x="255" y="200" font-size="10.5" fill="#0c4a6e">• Geniş kıta sahanlığı ve deltalar.</text>\n  <rect x="468" y="42" width="210" height="175" rx="10" fill="#fce7f3" stroke="#db2777" stroke-width="2"/>\n  <text x="573" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9d174d">AKDENİZ KIYILARI</text>\n  <text x="478" y="88" font-size="10.8" fill="#831843">• Toros Dağları Uzantısı:</text>\n  <text x="486" y="105" font-size="10.5" fill="#831843">Genel olarak Boyuna kıyı tipi</text>\n  <text x="478" y="128" font-size="10.8" fill="#831843">• Teke Yarımadası (Kaş - Finike):</text>\n  <text x="486" y="145" font-size="10.5" fill="#831843">Dalmaçya kıyı tipi (kıyıya paralel</text>\n  <text x="486" y="160" font-size="10.5" fill="#831843">uzanan dağ sırtlarının adalaşması)</text>\n  <text x="478" y="184" font-size="10.8" fill="#831843">• Silifke - Mersin Arası:</text>\n  <text x="486" y="201" font-size="10.5" fill="#831843">Kalanklı (karstik kanyon) kıyı</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Gerçek kıyı uzunluğu ile kuş uçuşu kıyı uzunluğu arasındaki fark en fazla Enine kıyıların bulunduğu Ege\'dedir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TÜRKİYE\'DE YERYÜZÜ ŞEKİLLERİNİN GENEL ÖZELLİKLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#5b21b6">YÜKSELTİ, EĞİM VE UZANIŞ DOĞRULTUSU</text>\n  <text x="35" y="88" font-size="11.2" fill="#4c1d95">• Ortalama yükselti fazladır (1142 m) ve batıdan</text>\n  <text x="45" y="104" font-size="11.2" fill="#4c1d95">doğuya doğru gidildikçe yükselti düzenli artar.</text>\n  <text x="35" y="128" font-size="11.2" fill="#4c1d95">• Alp-Himalaya kuşağında yer aldığı için dağlar</text>\n  <text x="45" y="144" font-size="11.2" fill="#4c1d95">genellikle doğu-batı doğrultusunda uzanır.</text>\n  <text x="35" y="168" font-size="11.2" fill="#4c1d95">• Genç oluşumlu (Senozoyik\'te yükselmiş) bir arazi</text>\n  <text x="45" y="184" font-size="11.2" fill="#4c1d95">olduğu için eğim, engebe ve vadi derinliği fazladır.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9f1239">BAŞLICA ANA YER ŞEKİLLERİ (DAĞ-OVA-PLATO)</text>\n  <text x="370" y="88" font-size="11.2" fill="#881337">• Kıvrım Dağları: Kuzey Anadolu ve Toros Dağları.</text>\n  <text x="370" y="112" font-size="11.2" fill="#881337">• Kırık (Horst) Dağları: Kaz, Madra, Yunt, Bozdağ,</text>\n  <text x="380" y="128" font-size="11.2" fill="#881337">Aydın ve Menteşe Dağları (Batı Anadolu).</text>\n  <text x="370" y="152" font-size="11.2" fill="#881337">• Volkanik Dağlar: Ağrı, Tendürek, Süphan, Nemrut,</text>\n  <text x="380" y="168" font-size="11.2" fill="#881337">Erciyes, Hasan, Melendiz, Karadağ, Karacadağ.</text>\n  <text x="370" y="192" font-size="11.2" fill="#881337">• Platolar (toptan yükselme) ve Delta/Tektonik Ovalar.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Türkiye\'de en etkili dış kuvvet akarsulardır; kısa mesafede yükselti değişimi iklim ve biyoçeşitliliği artırır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
